:

    .monroe-pack-toast {
        position: fixed;
        right: 1.1rem;
        bottom: 1.1rem;
        z-index: 9000;
        max-width: 280px;
        background: linear-gradient(135deg, #134e4a, #1b6e63);
        color: #fff;
        border-radius: 14px;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.22);
        padding: 0.7rem 0.9rem;
        display: flex;
        align-items: center;
        gap: 0.55rem;
        opacity: 0;
        transform: translateY(12px) scale(0.96);
        transition: opacity 0.35s ease, transform 0.35s ease;
        pointer-events: none;
    }
    .monroe-pack-toast.is-visible {
        opacity: 1;
        transform: translateY(0) scale(1);
        pointer-events: auto;
    }
    .monroe-pack-toast__link {
        display: flex;
        align-items: center;
        gap: 0.55rem;
        color: #fff;
        text-decoration: none;
        font-weight: 700;
        font-size: 0.86rem;
        line-height: 1.25;
    }
    .monroe-pack-toast__icon { font-size: 1.35rem; flex: none; }
    .monroe-pack-toast__dismiss {
        position: absolute;
        top: -8px;
        right: -8px;
        width: 22px;
        height: 22px;
        border-radius: 50%;
        border: none;
        background: #fff;
        color: #134e4a;
        font-size: 0.9rem;
        line-height: 1;
        cursor: pointer;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
    }
    @media (max-width: 480px) {
        .monroe-pack-toast { right: 0.6rem; bottom: 0.6rem; left: 0.6rem; max-width: none; }
    }
